function parseKeyValue(s: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const seg of s.split(';')) {
    if (!seg.trim()) continue;
    const i = seg.indexOf('=');
    if (i < 0) throw new Error(`bad segment: ${seg}`);
    out[seg.slice(0, i).trim()] = seg.slice(i + 1).trim();
  }
  return out;
}

